    record Fixture(Context context,FamilyCurrentRelationQueries queries,PlanningReadReceipt receipt,Path sidecar,MemoryArchive archive,AtomicInteger admissions,AtomicInteger roots){ }
    Fixture fixture(String id,ObjectNode nativeValue,ObjectNode material)throws Exception{
        Context c=context();var root=root(c);var archive=new MemoryArchive();var calls=new AtomicInteger();var reads=new AtomicInteger();var exports=new FamilyRelationMaterialExports(directory,()->archive);var queries=new FamilyCurrentRelationQueries(SOURCE,ref->{reads.incrementAndGet();assertEquals(ROOT_REF,ref);return root;},request->calls.incrementAndGet(),exports);
        var args=queries.canonicalArguments(c,app(InteractionJson.F.objectNode().put("expected_native_revision",REV)),ROOT_REF);var request=new PlanningReadRequest(c.before(),c.source(),c.sessionId(),queries.contract().operation(),args,c.deadline());NativeRequest prepared=queries.contract().prepare(request,id);JsonNode fields=InteractionJson.parse(prepared.additionalFields());assertFalse(fields.has("heir_character_id"));assertFalse(fields.has("candidate_character_id"));assertEquals(1,fields.get("guardian_factory_sidecar_hash_schema").intValue());
        Path path=Path.of(fields.get("guardian_factory_sidecar_path").textValue());byte[] original=raw(material).bytes();Files.write(path,original);ObjectNode command=command(id,nativeValue);command.set("guardian_factory_discovery_v1",hashProof(original));return new Fixture(c,queries,receipt(c,request,FamilyCurrentRelationQueries.CONTRACT_ID,id,command),path,archive,calls,reads);
    }
    @Test void actualOwnedExportDirectoryWorksAndRejectsReplacement()throws Exception{
        Path owned=Files.createDirectory(directory.resolve("owned"));var archive=new MemoryArchive();
        var exports=new FamilyRelationMaterialExports(owned,()->archive);
        Path first=Path.of(exports.prepare("owned-query"));assertEquals(owned.toRealPath(),first.getParent().getParent());
        byte[] bytes=raw(sidecar("owned-query")).bytes();Files.write(first,bytes);Context c=context();
        var request=new PlanningReadRequest(c.before(),c.source(),c.sessionId(),new OperationKey(FamilyCurrentRelation.STEP),
                app(InteractionJson.F.objectNode().put("expected_native_revision",REV)),c.deadline());
        ObjectNode frame=command("owned-query",relation());frame.set("guardian_factory_discovery_v1",hashProof(bytes));
        var actual=receipt(c,request,FamilyCurrentRelationQueries.CONTRACT_ID,"owned-query",frame);
        var captured=exports.capture(actual);assertArrayEquals(bytes,captured.original().bytes());assertEquals(1,archive.writes);
        Files.writeString(first,"{}");assertThrows(IllegalArgumentException.class,()->exports.capture(actual));
        assertArrayEquals(bytes,exports.archived(actual).original().bytes());assertEquals(1,archive.writes);
        assertTrue(Files.isDirectory(first.getParent()));Files.move(owned,directory.resolve("old-owned"));Files.createDirectory(owned);
        assertThrows(IllegalArgumentException.class,()->exports.prepare("replacement-query"));assertEquals(1,archive.writes);
    }
    @Test void actualRootCanonicalEncoderLiveCaptureAndPureReplayShareOneContract()throws Exception{
        Fixture f=fixture("fixture-current",relation(),sidecar("fixture-current"));var live=f.queries().contract().decode(f.receipt());assertEquals(1,f.admissions().get());assertTrue(f.roots().get()>=2);assertEquals(FamilyCurrentRelation.State.AVAILABLE,f.queries().decodeReceipt(f.receipt()).state());assertEquals(List.of(),f.queries().decodeReceipt(f.receipt()).spouses().orElseThrow());JsonNode body=OpportunityJson.toNode(live);assertTrue(body.get("guardian_factory_materials_v2").get("native_hash_proof_verified").booleanValue());assertEquals(new BigInteger("18446744073709551615"),body.get("guardian_factory_materials_v2").get("observation").get("pump_epoch").bigIntegerValue());
        Files.writeString(f.sidecar(),"{}");int admissions=f.admissions().get();assertEquals(live,f.queries().contract().replay(f.receipt()));Files.delete(f.sidecar());assertEquals(live,f.queries().contract().replay(f.receipt()));assertEquals(admissions,f.admissions().get());assertEquals(1,f.archive().writes);assertEquals(live,app((ObjectNode)OpportunityJson.toNode(live)));
    }
