    /** Test-only exact bytes dictionary. It grants no continuity/session or publication membership. */
    static final class MemoryArchive implements ActionPorts.OutcomeArchive{
        final Map<ExactRef,RawJson> originals=new HashMap<>();int writes;
        public ExactRef preserveMaterial(RawJson original){ExactRef ref=new ExactRef("fixture/material/"+DriverJson.sha256(original.bytes()),original.bytes().length,DriverJson.sha256(original.bytes()));originals.put(ref,original);writes++;return ref;}
        public RawJson loadMaterial(ExactRef ref){return java.util.Objects.requireNonNull(originals.get(ref),"original material absent");}
        public ExactRef materialReference(String sha,long bytes){return originals.keySet().stream().filter(ref->ref.sha256().equals(sha)&&ref.bytes()==bytes).findFirst().orElseThrow();}
        public ExactRef materialReferenceOf(RawJson original){return materialReference(DriverJson.sha256(original.bytes()),original.bytes().length);}
        private static UnsupportedOperationException unused(){return new UnsupportedOperationException("fixture has no native/action/writer authority");}
        public ExactRef preserve(NativeActionPort.DispatchOutcome value){throw unused();}public NativeActionPort.DispatchOutcome load(ExactRef ref){throw unused();}public ExactRef preserveRequest(NativeRequest value){throw unused();}public NativeRequest loadRequest(ExactRef ref){throw unused();}public ExactRef referenceOf(NativeActionPort.DispatchOutcome value){throw unused();}public ExactRef requestReferenceOf(NativeRequest value){throw unused();}public ExactRef preserveRead(PlanningReadReceipt value){throw unused();}public PlanningReadReceipt loadRead(ExactRef ref){throw unused();}public ExactRef readReferenceOf(PlanningReadReceipt value){throw unused();}public ExactRef preserveRecord(ActionRecord value){throw unused();}public ActionRecord loadRecord(ExactRef ref){throw unused();}public ExactRef recordReferenceOf(ActionRecord value){throw unused();}public ExactRef preserveReceipt(ActionReceipt value){throw unused();}public ActionReceipt loadReceipt(ExactRef ref){throw unused();}public ExactRef receiptReferenceOf(ActionReceipt value){throw unused();}public ExactRef preserveNativeFrame(NativeObservationPort.ObservedFrame value){throw unused();}public byte[] loadNativeFrame(ExactRef ref){throw unused();}
    }
